def type_info(code: str | None) -> tuple[str, str]:
    """(name, category); unknown codes come back as themselves with category 'unknown'."""
    if not code:
        return "unknown", "unknown"
    return TYPES.get(code.upper(), (code.upper(), "unknown"))
